// Client is llm.search/v1 over HTTP, for the CLI and other apps. It implements Search; the token it was made with is
// the credential, so the extkit.Auth argument is ignored.
type Client struct{ c *extkit.Caller }

// NewClient calls llm.search/v1 on the app at baseURL with token (a PocketBase auth token or an API token).
func NewClient(baseURL, token string, hc *http.Client) *Client {
	return &Client{W.Client(baseURL, token, hc)}
}

var _ Search = (*Client)(nil)

func (c *Client) Status(ctx context.Context, _ extkit.Auth) (Status, error) {
	var out Status
	return out, c.c.Call(ctx, "GET", "status", struct{}{}, &out)
}

